`timescale 1ns/1ps
// Q15 analytic spectral envelopes; no recorded/PCM samples.
// Warm piano profiles; the reserved bank attenuates 3f0/5f0/7f0 and supplies a weak unison mode.
module piano_spectrum_rom(input wire clk,input wire [8:0] age,
    input wire [3:0] octave,input wire [4:0] oscillator_index,
    output reg [15:0] gain);
    wire [1:0] register_index=octave<=3 ? 2'd0 : octave==4 ? 2'd1 : 2'd2;
    wire [1:0] band=(oscillator_index==0) ? 2'd0 :
        (oscillator_index<3) ? 2'd1 : (oscillator_index<7) ? 2'd2 : 2'd3;
    wire odd_selected=(oscillator_index==2 || oscillator_index==4 || oscillator_index==6);
    wire odd_band=(oscillator_index!=2);
    wire [12:0] coefficient_address=(oscillator_index==31) ?
        {4'b1111,7'd0,register_index} : odd_selected ?
        {2'b11,register_index,odd_band,age[8:1]} : {register_index,band,age};
    reg [15:0] coefficients[0:8191] /* synthesis syn_romstyle="block_rom" */;
